mapper.select:
select t.machine_id,t.machine_id machineId,t.photo_jpg,t.photo_jpg photoJpg,t.ext_machine_id,t.ext_machine_id
extMachineId,t.staff_name,t.staff_name staffName,t.log_id,t.log_id logId,t.community_id,t.community_id
communityId,t.staff_id,t.staff_id staffId,t.ext_staff_id,t.ext_staff_id extStaffId,t.machine_name,t.machine_name
machineName,t.create_time createTime
from manual_open_door_log t
where 1 =1

    and t.machine_id= #{machineId}


    and t.photo_jpg= #{photoJpg}


    and t.ext_machine_id= #{extMachineId}


    and t.staff_name= #{staffName}


    and t.log_id= #{logId}


    and t.community_id= #{communityId}


    and t.staff_id= #{staffId}


    and t.ext_staff_id= #{extStaffId}


    and t.machine_name= #{machineName}

order by t.create_time desc

    limit #{page}, #{row}

select count(1) count
from manual_open_door_log t
where 1 =1

    and t.machine_id= #{machineId}


    and t.photo_jpg= #{photoJpg}


    and t.ext_machine_id= #{extMachineId}


    and t.staff_name= #{staffName}


    and t.log_id= #{logId}


    and t.community_id= #{communityId}


    and t.staff_id= #{staffId}


    and t.ext_staff_id= #{extStaffId}


    and t.machine_name= #{machineName}
